// Category A — a sheet of graph paper for placing several things on one numbered scale: the columns
// are the scale's steps, each row is one thing, and a row's marked cells show where it sits. Every
// row is its own React Aria RadioGroup (horizontal), so arrow keys walk a row and Tab moves between
// rows; the value a row picks is one column. What the marks around that column mean (a window of
// sizes, a range) is the consumer's, which is why a row takes its marks rather than deriving them.
//
// Not a SegmentedControl: a row here holds a dozen or more cells at the minimum target width, with
// no room for a word in any of them, and the rows share one column header so they can be compared.
import { Label, Radio, RadioGroup } from "react-aria-components";
import type { RadioGroupProps } from "react-aria-components";
import { createContext, useContext, useId } from "react";
import type { CSSProperties, ReactNode, Ref } from "react";
import "./StepLadder.css";

export interface StepLadderColumn {
  /** The step this column stands for. */
  value: number;
  /** The column's header, as read (a size in px, a rung number). */
  label: string;
}

const StepLadderColumnsContext = createContext<readonly StepLadderColumn[]>([]);

export interface StepLadderProps {
  /** The scale's steps, in order; every row offers one cell per column. */
  columns: readonly StepLadderColumn[];
  /** Names the whole sheet (optional when its container already does). */
  label?: string;
  /** StepLadderRow children. */
  children?: ReactNode;
  /** Names the sheet when no visible `label` does. */
  "aria-label"?: string;
  /** Additional class (optional). sd-step-ladder is always preserved. */
  className?: string;
  style?: CSSProperties;
  /** Forwarded to the root <div>. */
  ref?: Ref<HTMLDivElement>;
}

export interface StepLadderRowProps
  extends Omit<RadioGroupProps, "className" | "style" | "children" | "value" | "defaultValue" | "onChange" | "orientation"> {
  /** The row's name, drawn in the first column. */
  label: string;
  /** The column this row has picked. */
  value: number;
  /** Called with the column a person picks. */
  onChange?: (value: number) => void;
  /** A short mark to draw in a cell, by column value. A marked cell is filled. */
  marks?: Readonly<Record<number, string>>;
  /** Lowest pickable column; cells below it are disabled. */
  minValue?: number;
  /** Highest pickable column; cells above it are disabled. */
  maxValue?: number;
  /** Additional class (optional). sd-step-ladder__row is always preserved. */
  className?: string;
  /** Forwarded to the row's radiogroup <div>. */
  ref?: Ref<HTMLDivElement>;
}

export function StepLadder({ columns, label, children, className, style, ref, ...props }: StepLadderProps) {
  const labelId = useId();
  return (
    <div
      {...props}
      ref={ref}
      role="group"
      aria-labelledby={label ? labelId : undefined}
      className={className ? `sd-step-ladder ${className}` : "sd-step-ladder"}
      // The column count is the one fact CSS cannot read off the markup: a local intermediate, not a token.
      style={{ ...style, "--sd-step-ladder-columns-current": columns.length } as CSSProperties}
    >
      {label && (
        <span id={labelId} className="sd-step-ladder__label sd-type-label-medium">
          {label}
        </span>
      )}
      {/* The header repeats what every cell's own name says, so it is hidden from assistive tech. */}
      <div aria-hidden="true" className="sd-step-ladder__header">
        <span />
        {columns.map((c) => (
          <span key={c.value} className="sd-step-ladder__tick sd-type-caption-medium">
            {c.label}
          </span>
        ))}
      </div>
      <StepLadderColumnsContext.Provider value={columns}>{children}</StepLadderColumnsContext.Provider>
    </div>
  );
}

export function StepLadderRow({
  label,
  value,
  onChange,
  marks = {},
  minValue = -Infinity,
  maxValue = Infinity,
  className,
  ...props
}: StepLadderRowProps) {
  const columns = useContext(StepLadderColumnsContext);
  return (
    <RadioGroup
      {...props}
      orientation="horizontal"
      value={String(value)}
      onChange={(v) => onChange?.(Number(v))}
      className={className ? `sd-step-ladder__row ${className}` : "sd-step-ladder__row"}
    >
      <Label className="sd-step-ladder__row-label sd-type-label-medium">{label}</Label>
      {columns.map((c) => {
        const mark = marks[c.value];
        return (
          <Radio
            key={c.value}
            value={String(c.value)}
            isDisabled={c.value < minValue || c.value > maxValue}
            // The column's header is hidden, so each cell carries it: "title 24 · L".
            aria-label={mark ? `${label} ${c.label} · ${mark}` : `${label} ${c.label}`}
            data-marked={mark ? true : undefined}
            className="sd-step-ladder__cell sd-type-label-medium"
          >
            {mark}
          </Radio>
        );
      })}
    </RadioGroup>
  );
}

/* StepLadder.css — .sd-step-ladder (+ __label, __header, __tick, __row, __row-label, __cell)
   A grid whose first column holds the row names and whose other columns are the scale's steps. The
   header and every row are subgrids of it, so all cells of one step share a column. Rows are ruled
   the way Table rules its rows, one line under each row and no columns drawn: the header and the
   alignment carry the columns, so only the marks stand out. */
.sd-step-ladder {
  display: grid;
  grid-template-columns:
    max-content
    repeat(var(--sd-step-ladder-columns-current), minmax(var(--sd-step-ladder-cell-size), 1fr));
  min-width: 0;
}

.sd-step-ladder__label {
  grid-column: 1 / -1;
  margin-block-end: var(--sd-step-ladder-gap);
  color: var(--sd-step-ladder-label-foreground);
}

.sd-step-ladder__header,
.sd-step-ladder__row {
  grid-column: 1 / -1;
  display: grid;
  grid-template-columns: subgrid;
  align-items: center;
}
/* The row draws its own rule, so a marked band's rounded ends sit above the line instead of bending it. */
.sd-step-ladder__row {
  border-block-end: var(--sd-step-ladder-cell-border-width) solid var(--sd-step-ladder-cell-border);
}

.sd-step-ladder__tick {
  text-align: center;
  /* A two-digit step is one number: the reset's break-word would split it down a narrow column. */
  white-space: nowrap;
  color: var(--sd-step-ladder-tick-foreground);
  font-variant-numeric: tabular-nums;
}

.sd-step-ladder__row-label {
  padding-inline-end: var(--sd-step-ladder-row-label-gap);
  align-self: stretch;
  display: flex;
  align-items: center;
  color: var(--sd-step-ladder-row-label-foreground);
  white-space: nowrap;
}

.sd-step-ladder__cell {
  position: relative;
  /* A cell is a box centring its input: its role class sizes the digit and must not pad the cell. */
  padding-inline: 0;
  isolation: isolate;
  display: grid;
  place-items: center;
  min-block-size: var(--sd-step-ladder-cell-size);
  border: none;
  background: transparent;
  cursor: pointer;
  outline: none;
  transition:
    background-color var(--sd-duration-moderate) var(--sd-easing-standard),
    box-shadow var(--sd-duration-moderate) var(--sd-easing-standard);
  --sd-step-ladder-cell-state-hover-current: var(--sd-state-hover);
  --sd-step-ladder-cell-state-pressed-current: var(--sd-state-pressed);
}
.sd-step-ladder__cell[data-marked] {
  background: var(--sd-step-ladder-cell-background-marked);
  color: var(--sd-step-ladder-cell-foreground-marked);
  --sd-step-ladder-cell-state-hover-current: var(--sd-state-hover-brand-subtle);
  --sd-step-ladder-cell-state-pressed-current: var(--sd-state-pressed-brand-subtle);
}
/* A run of marked cells is one band: only its outer ends round, so S, M and L read as one chip. A
   lone mark is both ends, a pill of its own. */
.sd-step-ladder__cell[data-marked]:not([data-marked] + *) {
  border-start-start-radius: var(--sd-step-ladder-cell-radius);
  corner-start-start-shape: round;
  border-end-start-radius: var(--sd-step-ladder-cell-radius);
  corner-end-start-shape: round;
}
.sd-step-ladder__cell[data-marked]:not(:has(+ [data-marked])) {
  border-start-end-radius: var(--sd-step-ladder-cell-radius);
  corner-start-end-shape: round;
  border-end-end-radius: var(--sd-step-ladder-cell-radius);
  corner-end-end-shape: round;
}

.sd-step-ladder__cell::after {
  content: "";
  position: absolute;
  inset: 0;
  background: transparent;
  border-radius: inherit;
  corner-shape: inherit;
  pointer-events: none;
  z-index: -1;
  transition: background-color var(--sd-duration-moderate) var(--sd-easing-standard);
}
.sd-step-ladder__cell[data-hovered]::after {
  background: var(--sd-step-ladder-cell-state-hover-current);
}
.sd-step-ladder__cell[data-pressed]::after {
  background: var(--sd-step-ladder-cell-state-pressed-current);
}

/* Over its neighbours, whose fills would otherwise paint across the ring. */
.sd-step-ladder__cell[data-focus-visible] {
  z-index: 1;
  box-shadow: 0 0 0 var(--sd-state-focus-ring-width) color-mix(in srgb, var(--sd-state-focus-ring) calc(var(--sd-state-focus-ring-opacity) * 100%), transparent);
  outline: var(--sd-state-focus-ring-width) solid transparent;
}

/* Nothing fades out of reach: an empty cell paints nothing to fade, while a marked cell's mark is
   the row's own value and must read at full strength. An unreachable cell answers no hover, which
   is the whole cue. */
.sd-step-ladder__cell[data-disabled] {
  cursor: default;
}
